#!/bin/bash
# Правки пользователя (сессия 4): (1) вместо каменного уступа на рельсе мини-фон: земля, дорожка, трава; (2) капсула-фундамент целиком объёмная (верхняя плоскость в самом арте).
cd /home/user/projects/matchhold/rebranding || exit 1
S=${S:-/tmp/claude-1000/-home-user-projects-matchhold/8cf97f12-1c34-4a07-9e32-fb51c227da2b/scratchpad}
DAY='Cozy fantasy village match-3 game art. Warm, soft, matte hand-painted 3D look: chunky rounded forms, soft ambient occlusion, gentle gradients, NO glossy plastic highlights, NO specular shine. Warm afternoon light from the top-left, soft warm shadow toward the bottom-right. A thin outline slightly darker than the object own hue, never black. Palette: warm sand beige, honey gold, chestnut brown, sage green, muted terracotta, cream white.'
gen() { # out refs size key prompt
  [ -f "$1" ] && return
  codex exec -m gpt-5.6-terra -c model_reasoning_effort=low --sandbox workspace-write \
  "Use the built-in image_gen tool (imagegen skill) to generate ONE image. The attached images are references: follow them where the prompt says, otherwise for style, palette and material only. Target size $3 (if the native size differs, resize the whole picture to FIT INSIDE with ImageMagick and pad with the key colour; NEVER crop, NEVER stretch; the subject stays complete with at least 4% empty key-colour margin). PNG. $5 The whole background is a solid flat $4 (no gradient, no shadow, no fringe); nothing in the artwork is that colour. Avoid: people, text, letters, logos, watermark, UI, photorealism, gloss, lens flare, pixel art, thick black outlines, buildings, trees. Save the final PNG to exactly: /home/user/projects/matchhold/rebranding/$1 . Do not overwrite existing files. Print the saved path and dimensions." -i $2 \
  > "$S/$(basename $1).log" 2>&1
}
for v in 1 2; do
gen out/env/ground/ground_strip_v$v.png out/env/buildings/ref_row.png 1536x256 '#FF00FF' "$DAY A long horizontal strip of village ground seen from a high three-quarter angle, like the walkable top of a garden wall: a warm sandy dirt footpath with a few pebbles runs lengthwise through the middle, grass verges on both sides with small tufts of grass and a few tiny white and pale-yellow flowers, uneven grass tufts along the back (top) edge of the strip, and a clean straight lower edge like a thin turf-and-soil lip. About six times wider than tall, it fills the canvas width edge to edge, the left and right ends continue seamlessly (same look at both ends). Nothing rises above the grass tufts." &
gen out/env/capsules/capsule_block3_v$v.png "out/env/capsules/capsule_stone3_v2.png" 1120x700 '#00FF00' "$DAY The same 3-segment stone resource capsule as the attached image (same round empty sockets on the left and long empty pill-shaped troughs, same brass rims, corner plates and rivets, same warm grey-beige stone masonry), but drawn as a slightly THREE-DIMENSIONAL slab: seen from a little above, the flat TOP surface of the stone slab is visible as a lighter band of flat stone slabs along the whole top (about 22% of the total height, the back edge slightly narrower than the front edge for perspective), and below it the front face with the 3 segments exactly as in the attached image, with a thin visible darker stone base at the bottom. Keep the sockets and troughs empty and dark brown inside: no fill, no icons, no text. No moss, no plants. Matte, no gloss. The whole slab fills the canvas edge to edge horizontally with a small margin, exactly one slab." &
done
wait; echo DONE
